// Узел для разбиения длинных сообщений на части по 2000 символов
// с сохранением целостности предложений

const fullText = $input.first().json.output || $input.first().json.text || '';
const chatId = $('Max Trigger1').first().json.message.recipient.chat_id;
const MAX_LENGTH = 2000;

// Функция разбиения текста с сохранением предложений
function splitIntoSentences(text, maxLength) {
    if (text.length <= maxLength) {
        return [text];
    }

    const chunks = [];
    let currentChunk = '';

    // Разбиваем на предложения (по . ! ? с пробелом или концом строки)
    const sentences = text.split(/(?<=[.!?])\s+/);

    for (const sentence of sentences) {
        // Если одно предложение длиннее maxLength - принудительно режем
        if (sentence.length > maxLength) {
            if (currentChunk) {
                chunks.push(currentChunk.trim());
                currentChunk = '';
            }
            for (let i = 0; i < sentence.length; i += maxLength) {
                chunks.push(sentence.slice(i, i + maxLength));
            }
            continue;
        }

        // Если добавление предложения превысит лимит
        if ((currentChunk + sentence).length > maxLength) {
            if (currentChunk) {
                chunks.push(currentChunk.trim());
                currentChunk = '';
            }
        }
        currentChunk += (currentChunk ? ' ' : '') + sentence;
    }

    if (currentChunk) {
        chunks.push(currentChunk.trim());
    }

    return chunks;
}

// Разбиваем текст
const messageChunks = splitIntoSentences(fullText, MAX_LENGTH);

// Возвращаем массив сообщений для отправки
return messageChunks.map((chunk, index) => ({
    json: {
        sendTo: "chat",
        chatId: chatId,
        text: index === 0 ? chunk : `[продолжение]\n${chunk}`,
        additionalFields: {}
    }
}));

